<?php
namespace App\Http\Middleware;use App\Models\ScimAccessToken;use App\Models\Workspace;use Closure;use Illuminate\Http\Request;use Symfony\Component\HttpFoundation\Response;
/** Provides authenticate scim token behavior within the WorkIntel application. */ class AuthenticateScimToken{/** Executes the command, job, or request handler. */ public function handle(Request $request,Closure $next):Response{$raw=$request->bearerToken();abort_unless($raw&&str_starts_with($raw,'wiscim_'),401,'SCIM bearer token required.');$token=ScimAccessToken::where('token_hash',hash('sha256',$raw))->first();abort_unless($token&&!$token->revoked_at&&(!$token->expires_at||$token->expires_at->isFuture()),401,'SCIM token is invalid, expired or revoked.');$workspace=Workspace::find($token->workspace_id);abort_unless($workspace&&$workspace->status==='active',401);$token->update(['last_used_at'=>now(),'last_used_ip'=>$request->ip()]);$request->attributes->set('scimToken',$token);$request->attributes->set('workspace',$workspace);return $next($request);}}
